12	    CHAOSArmTLB::CHAOSArmTLB(const CHAOSArmTLBParams &p)
13	        : SimObject(p),
14	          tlb(p.tlb),
15	          probability(p.probability),
16	          fault_type_enum(stringToFaultType(p.faultType)),
17	          fault_mask(p.faultMask),
18	          num_bits_to_change(p.bitsToChange),
19	          target_field(p.targetField),
20	          pfn_offset(p.pfnOffset),
21	          first_clock(Cycles(p.firstClock)),
22	          last_clock(Cycles(p.lastClock)),
23	          max_faults(p.maxFaults),
24	          faults_injected_count(0),
25	          rng_seed(p.rngSeed),
26	          write_log(p.writeLog),
27	          stats(nullptr)
28	    {
29	        if (probability > 0.0f) {
30	            log_stream = simout.create("armtlb_injections.log", false, true);
31	            if (!log_stream || !log_stream->stream()) {
32	                panic("CHAOSArmTLB: Could not open log file");
33	            }
34	            stats = std::make_unique<CHAOSArmTLBStats>(this);
35	            rng.seed(rng_seed != 0 ? rng_seed : rd());
36	            random_fault_distribution = std::discrete_distribution<int>(
37	                {0.9, 0.05, 0.05});  // bit_flip / stuck0 / stuck1
38	            // SELF-ATTACH to the target TLB (same pattern as CHAOSLSQFwd:
39	            // cpu->lsqFwd = this). The TLB's `chaosTLB` field is public; we
40	            // set it here so TLB::lookup can reach this injector. `tlb` was
41	            // passed as a Param and is constructed first. Safe because
42	            // TLB::lookup only reads chaosTLB during translate(), long after
43	            // SimObject construction. This avoids needing a python binding
44	            // for setChaosTLB (which has none, like setLSQFwd).
45	            // D6: warn (not silent) if tlb is NULL — a misconfigured run
46	            // would otherwise silently inject nothing.
47	            if (tlb) {
48	                tlb->chaosTLB = this;
49	            } else {
50	                warn("CHAOSArmTLB: tlb param is NULL — SELF-ATTACH failed; "
51	                     "TLB hook will be inactive.\n");
52	            }
53	        }
54	    }
