102	    {
103	        if (!entry || probability <= 0.0f) return;
104	        // D1 fix: enforce the [first_tick, last_tick] window (curTick domain).
105	        // Before this fix the window was "advisory only" and never checked,
106	        // so injection fired from sim start. last_tick==0 means unrestricted.
107	        Tick now = curTick();
108	        if (now < first_tick) return;
109	        if (last_tick != 0 && now > last_tick) return;
110	        if (max_faults != 0 && faults_injected_count >= max_faults) return;
111	
112	        // Probability gate: per-lookup Bernoulli. D5: use >= (consistent with
113	        // CHAOSLSQFwd; was >, which let probDist==probability slip through).
114	        std::uniform_real_distribution<float> probDist(0.0f, 1.0f);
115	        if (probDist(rng) >= probability) return;
116	
117	        // §5.7B: field-level injection. targetField selects which TlbEntry
118	        // field is corrupted (pfn/ap/xn/attridx/ng/asid); pfnOffset (F5)
119	        // substitutes the pfn with pfn+offset (another page frame — proxy
120	        // for another live page; TLB container enumeration is not public,
121	        // honest proxy documented in the param help).
122	        if (pfn_offset != 0 && target_field == "pfn") {
123	            // F5 directed: pfn -> pfn + offset (legal-domain substitute).
124	            Addr old_pfn = entry->pfn;
125	            entry->pfn = old_pfn + pfn_offset;
126	            stats->numFaultsInjected++;
127	            ++faults_injected_count;
128	            if (write_log) {
129	                *(log_stream->stream())
130	                    << "Tick: " << curTick()
131	                    << ", Site: arm_tlb_lookup_hit"
132	                    << ", Mode: pfn_to_offset (F5)"
133	                    << ", VA: 0x" << std::hex << va
134	                    << ", old_pfn: 0x" << old_pfn
135	                    << ", new_pfn: 0x" << entry->pfn
136	                    << ", pfnOffset: 0x" << pfn_offset << std::dec
137	                    << std::endl;
138	            }
139	            return;
140	        }
141	        if (target_field == "ap") {
142	            uint8_t old_ap = entry->ap;
143	            std::uniform_int_distribution<int> apd(0, 2);
144	            entry->ap ^= (uint8_t)(fault_mask ? (fault_mask & 0xff)
